// Drift reads these getters during code generation: a `check` constraint that
// names its own column is never run as a recursive call.
// ignore_for_file: recursive_getters

import 'package:drift/drift.dart';
import 'package:uuid/uuid.dart';

/// Public, because the code generated by drift calls it from another file.
String newId() => const Uuid().v4();

enum PaymentMethod {
  cash,
  mobileMoney,

  /// Arrears withheld from the member's own pot at payout.
  withheld,
}

/// Payout methods: a pot is handed in cash or by mobile money.
enum PayoutMethod { cash, mobileMoney }

/// The only account of the app. Only password and recovery code hashes are
/// stored.
@DataClassName('Account')
class Accounts extends Table {
  @override
  String get tableName => 'account';

  TextColumn get id => text().clientDefault(newId)();
  TextColumn get username => text().withLength(min: 1)();
  BlobColumn get passwordHash => blob()();
  BlobColumn get passwordSalt => blob()();
  BlobColumn get recoveryCodeHash => blob()();
  BlobColumn get recoveryCodeSalt => blob()();

  /// Kept per account, so hashing can be strengthened later.
  IntColumn get iterations => integer()();
  IntColumn get failures => integer().withDefault(const Constant(0))();
  DateTimeColumn get lockedUntil => dateTime().nullable()();

  /// Successive lockouts since the last successful login: each lasts twice
  /// as long as the previous one.
  IntColumn get lockouts => integer().withDefault(const Constant(0))();
  DateTimeColumn get createdAt => dateTime().withDefault(currentDateAndTime)();

  @override
  Set<Column<Object>> get primaryKey => {id};
}

@DataClassName('TontineRow')
class Tontines extends Table {
  @override
  String get tableName => 'tontine';

  TextColumn get id => text().clientDefault(newId)();
  TextColumn get name => text().withLength(min: 1)();
  IntColumn get places => integer().check(places.isBiggerOrEqualValue(1))();
  IntColumn get contributionPerPlace => integer().check(
    contributionPerPlace.isBiggerThanValue(0) &
        // SQLite divides integers exactly: a multiple of 10 survives / 10 * 10.
        ((contributionPerPlace / const Constant(10)) * const Constant(10))
            .equalsExp(contributionPerPlace),
  )();
  IntColumn get tourDays => integer().check(tourDays.isBiggerOrEqualValue(1))();

  /// Day 1 of the tontine, `yyyy-mm-dd`.
  TextColumn get firstDay => text().withLength(min: 10, max: 10)();
  DateTimeColumn get createdAt => dateTime().withDefault(currentDateAndTime)();

  @override
  Set<Column<Object>> get primaryKey => {id};
}

@DataClassName('MemberRow')
@TableIndex(name: 'member_tontine', columns: {#tontineId})
class Members extends Table {
  @override
  String get tableName => 'member';

  TextColumn get id => text().clientDefault(newId)();
  TextColumn get tontineId => text().references(Tontines, #id)();
  TextColumn get name => text().withLength(min: 1)();
  TextColumn get phone => text().nullable()();

  /// Order in which members were entered.
  IntColumn get position => integer()();
  DateTimeColumn get createdAt => dateTime().withDefault(currentDateAndTime)();

  @override
  Set<Column<Object>> get primaryKey => {id};
}

/// One beneficiary share of a tour: a full place (2 halves) or a half place
/// (1 half). A tour holds one full share or two half shares.
@DataClassName('SlotRow')
@TableIndex(name: 'slot_tontine_tour', columns: {#tontineId, #tour})
class Slots extends Table {
  @override
  String get tableName => 'slot';

  TextColumn get id => text().clientDefault(newId)();
  TextColumn get tontineId => text().references(Tontines, #id)();
  IntColumn get tour => integer().check(tour.isBiggerOrEqualValue(1))();
  TextColumn get memberId => text().references(Members, #id)();
  IntColumn get halves => integer().check(halves.isIn(const [1, 2]))();

  @override
  Set<Column<Object>> get primaryKey => {id};
}

/// Append-only: a payment is never edited, it is cancelled by a
/// [PaymentCancellations] row.
@DataClassName('PaymentRow')
@TableIndex(name: 'payment_member', columns: {#memberId})
@TableIndex(name: 'payment_tontine_day', columns: {#tontineId, #paidOn})
class Payments extends Table {
  @override
  String get tableName => 'payment';

  TextColumn get id => text().clientDefault(newId)();
  TextColumn get tontineId => text().references(Tontines, #id)();
  TextColumn get memberId => text().references(Members, #id)();
  IntColumn get amount => integer().check(amount.isBiggerThanValue(0))();
  TextColumn get method => textEnum<PaymentMethod>()();

  /// Day the money was received, `yyyy-mm-dd`.
  TextColumn get paidOn => text().withLength(min: 10, max: 10)();

  /// The payout this amount was withheld from, for [PaymentMethod.withheld].
  TextColumn get payoutId => text().nullable()();
  DateTimeColumn get createdAt => dateTime().withDefault(currentDateAndTime)();

  @override
  Set<Column<Object>> get primaryKey => {id};
}

@DataClassName('PaymentCancellationRow')
class PaymentCancellations extends Table {
  @override
  String get tableName => 'payment_cancellation';

  TextColumn get paymentId => text().references(Payments, #id)();
  TextColumn get reason => text().nullable()();
  DateTimeColumn get createdAt => dateTime().withDefault(currentDateAndTime)();

  @override
  Set<Column<Object>> get primaryKey => {paymentId};
}

/// Append-only: one row per beneficiary share handed out.
@DataClassName('PayoutRow')
@TableIndex(name: 'payout_tontine', columns: {#tontineId})
class Payouts extends Table {
  @override
  String get tableName => 'payout';

  TextColumn get id => text().clientDefault(newId)();
  TextColumn get tontineId => text().references(Tontines, #id)();
  TextColumn get slotId => text().references(Slots, #id)();

  /// Day the pot was handed, `yyyy-mm-dd`.
  TextColumn get paidOn => text().withLength(min: 10, max: 10)();
  IntColumn get pot => integer().check(pot.isBiggerThanValue(0))();
  IntColumn get collected => integer()();
  IntColumn get organizerTopUp =>
      integer().check(organizerTopUp.isBiggerOrEqualValue(0))();
  IntColumn get withheld => integer().check(withheld.isBiggerOrEqualValue(0))();
  IntColumn get handed => integer().check(handed.isBiggerOrEqualValue(0))();
  TextColumn get method => textEnum<PayoutMethod>()();
  DateTimeColumn get createdAt => dateTime().withDefault(currentDateAndTime)();

  @override
  Set<Column<Object>> get primaryKey => {id};
}

@DataClassName('PayoutCancellationRow')
class PayoutCancellations extends Table {
  @override
  String get tableName => 'payout_cancellation';

  TextColumn get payoutId => text().references(Payouts, #id)();
  TextColumn get reason => text().nullable()();
  DateTimeColumn get createdAt => dateTime().withDefault(currentDateAndTime)();

  @override
  Set<Column<Object>> get primaryKey => {payoutId};
}

/// History of tour swaps. The slots are swapped in the same transaction.
@DataClassName('TourSwapRow')
class TourSwaps extends Table {
  @override
  String get tableName => 'tour_swap';

  TextColumn get id => text().clientDefault(newId)();
  TextColumn get tontineId => text().references(Tontines, #id)();
  IntColumn get tourA => integer()();
  IntColumn get tourB => integer()();
  DateTimeColumn get createdAt => dateTime().withDefault(currentDateAndTime)();

  @override
  Set<Column<Object>> get primaryKey => {id};
}

/// Days the whole tontine does not contribute (a feast, the market closed):
/// every later contribution day, payout and the end move back by one day.
/// Only today or a later day can be skipped; a skip is removed while its day
/// has not passed, before it ever counted.
@DataClassName('SkippedDayRow')
@TableIndex(name: 'skipped_day_tontine', columns: {#tontineId})
class SkippedDays extends Table {
  @override
  String get tableName => 'skipped_day';

  TextColumn get id => text().clientDefault(newId)();
  TextColumn get tontineId => text().references(Tontines, #id)();

  /// The calendar day skipped, `yyyy-mm-dd`.
  TextColumn get day => text().withLength(min: 10, max: 10)();
  TextColumn get reason => text().nullable()();
  DateTimeColumn get createdAt => dateTime().withDefault(currentDateAndTime)();

  @override
  Set<Column<Object>> get primaryKey => {id};

  @override
  List<Set<Column<Object>>> get uniqueKeys => [
    {tontineId, day},
  ];
}
